<script setup>
import { computed, onMounted, ref } from 'vue'
import { Plus, Wallet, History, X, ArrowDownLeft, ArrowUpRight, Check, ReceiptText } from 'lucide-vue-next'
import { supabase } from '@/lib/supabase'
import { useAuthStore } from '@/stores/useAuthStore'
import { CLASS_ROSTER } from '@/data/classRoster'
import StudentProfileModal from '@/components/shared/StudentProfileModal.vue'
const auth=useAuthStore(), selectedStudentProfileId=ref(''), ledger=ref([]), payments=ref([]), expenses=ref([]), students=ref([]), allocations=ref([]), startMonth=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)), loading=ref(true), modal=ref(''), error=ref(''), success=ref('')
const localDateTime=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
const payment=ref({method:'qris',amount:20000,paid_at:localDateTime(),proof:null})
const expense=ref({title:'',amount:'',description:'',spent_at:new Date().toISOString().slice(0,10)}),editingExpense=ref(null),receiptFile=ref(null)
const months=computed(()=>Array.from({length:12},(_,i)=>new Date(startMonth.value.getFullYear(),startMonth.value.getMonth()+i,1)))
function monthPaid(studentId,month){return allocations.value.filter(a=>a.student_id===studentId&&a.month_start===month.toISOString().slice(0,10)).reduce((s,a)=>s+Number(a.amount),0)}
function monthTotal(month){return allocations.value.filter(a=>a.month_start===month.toISOString().slice(0,10)).reduce((s,a)=>s+Number(a.amount),0)}
function cellClass(amount){return amount<=0?'none':amount<10000?'low':amount<20000?'half':'full'}
const pending= computed(()=>payments.value.filter(p=>p.status==='pending'))
const accountProfiles=computed(()=>students.value.length?accountProfilesRaw.value:[])
const accountProfilesRaw=ref([])
const income=computed(()=>ledger.value.filter(x=>x.entry_type==='income').reduce((a,x)=>a+Number(x.amount),0))
const outgoing=computed(()=>ledger.value.filter(x=>x.entry_type==='expense').reduce((a,x)=>a+Number(x.amount),0))
const balance=computed(()=>income.value-outgoing.value)
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0))
async function load(){
  loading.value=true;error.value=''
  const [l,p,e,profiles,roster,al,st]=await Promise.all([
    supabase.from('cash_ledger').select('*,student:profiles!cash_ledger_student_id_fkey(display_name)').order('occurred_at',{ascending:false}),
    supabase.from('cash_payments').select('*,student:profiles!cash_payments_student_id_fkey(display_name)').order('submitted_at',{ascending:false}),
    supabase.from('cash_expenses').select('*').order('spent_at',{ascending:false}),
    supabase.from('profiles').select('id,display_name,attendance_number,role').eq('role','student').order('attendance_number',{ascending:true,nullsFirst:false}),
    supabase.rpc('get_class_roster_public'),
    supabase.from('cash_monthly_allocations').select('student_id,month_start,amount'),
    supabase.from('cash_settings').select('start_month,monthly_due').eq('id',true).maybeSingle()
  ])
  if(l.error)error.value=l.error.message
  if(roster.error)error.value=roster.error.code==='42P01'?'Roster kelas belum tersedia di database. Jalankan migration 20261109_finance_roster.sql di Supabase.':roster.error.message
  ledger.value=l.data||[]
  payments.value=await Promise.all((p.data||[]).map(async item=>{if(!item.proof_path)return item;const {data}=await supabase.storage.from('class-finance-proofs').createSignedUrl(item.proof_path,3600);return {...item,proof_url:data?.signedUrl||null}}))
  expenses.value=e.data||[]
  accountProfilesRaw.value=profiles.data||[]
  const profileByAttendance=new Map((profiles.data||[]).filter(x=>x.attendance_number).map(x=>[x.attendance_number,x]))
  const rosterRows=roster.data?.length?roster.data:CLASS_ROSTER
  students.value=rosterRows.map(row=>{const linked=(profiles.data||[]).find(x=>x.id===row.profile_id)||profileByAttendance.get(row.attendance_number);return {...row,profile_id:row.profile_id||linked?.id||null,display_name:row.full_name}})
  allocations.value=al.data||[]
  if(st.data?.start_month)startMonth.value=new Date(st.data.start_month+'T00:00:00')
  loading.value=false
}
function studentName(profileId){return students.value.find(s=>s.profile_id===profileId)?.full_name||payments.value.find(p=>p.student_id===profileId)?.student?.display_name||'Siswa'}
function openStudentProfile(profileId){if(profileId)selectedStudentProfileId.value=profileId}
function closeStudentProfile(){selectedStudentProfileId.value=''}
const myRosterEntry=computed(()=>students.value.find(s=>s.profile_id===auth.user?.id)||null)
async function linkStudent(row,profileId){const {error:e}=await supabase.from('class_roster').update({profile_id:profileId||null}).eq('attendance_number',row.attendance_number);if(e)error.value=e.message;else await load()}

async function submitPayment(){error.value='';if(!payment.value.amount||Number(payment.value.amount)<=0){error.value='Nominal pembayaran harus lebih dari nol.';return}if(payment.value.method==='qris'&&!payment.value.proof){error.value='Unggah bukti pembayaran QRIS terlebih dahulu.';return}let proof_path=null;if(payment.value.proof){const file=payment.value.proof;const path=`${auth.user.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('class-finance-proofs').upload(path,file,{upsert:false});if(up.error){error.value=up.error.message;return}proof_path=path}const {error:e}=await supabase.from('cash_payments').insert({student_id:auth.user.id,amount:Number(payment.value.amount),method:payment.value.method,paid_at:new Date(payment.value.paid_at).toISOString(),proof_path,status:'pending'});if(e)error.value=e.message;else{success.value='Pembayaran dikirim dan menunggu persetujuan admin.';modal.value='';await load()}}
function openPayment(){payment.value={method:'qris',amount:20000,paid_at:localDateTime(),proof:null};modal.value='payment'}
function openExpense(item=null){editingExpense.value=item;receiptFile.value=null;expense.value=item?{title:item.title,amount:item.amount,description:item.description,spent_at:item.spent_at}:{title:'',amount:'',description:'',spent_at:new Date().toISOString().slice(0,10)};modal.value='expense'}
async function addExpense(){let receipt_path=editingExpense.value?.receipt_path||null;if(receiptFile.value){const file=receiptFile.value;const path=`${auth.user.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('class-finance-proofs').upload(path,file);if(up.error){error.value=up.error.message;return}receipt_path=path}const data={...expense.value,amount:Number(expense.value.amount),receipt_path};const query=editingExpense.value?supabase.from('cash_expenses').update(data).eq('id',editingExpense.value.id):supabase.from('cash_expenses').insert({...data,created_by:auth.user.id});const {error:e}=await query;if(e)error.value=e.message;else{modal.value='';editingExpense.value=null;expense.value={title:'',amount:'',description:'',spent_at:new Date().toISOString().slice(0,10)};await load()}}
async function deleteExpense(item){if(!confirm(`Hapus pengeluaran "${item.title}"? Riwayat perubahan tetap tercatat.`))return;const {error:e}=await supabase.from('cash_expenses').delete().eq('id',item.id);if(e)error.value=e.message;else await load()}
async function review(p,status){const {error:e}=await supabase.from('cash_payments').update({status,reviewed_by:auth.user.id,reviewed_at:new Date().toISOString(),rejection_reason:status==='rejected'?'Tidak memenuhi verifikasi bukti pembayaran':null}).eq('id',p.id);if(e)error.value=e.message;else await load()}
onMounted(load)
</script>
<template><section class="finance-page"><header class="page-head"><span class="page-head__eyebrow">Keuangan kelas · XI B2</span><h1 class="page-head__title">Uang Kas</h1><p class="page-head__desc">Iuran rutin kelas sebesar Rp20.000 per siswa setiap bulan.</p></header>
<div class="balance-card"><div><span>Saldo kas saat ini</span><button class="history-icon" @click="modal='history'" aria-label="Riwayat uang kas"><History/></button></div><strong>{{money(balance)}}</strong><small>Total masuk {{money(income)}} · Total keluar {{money(outgoing)}}</small></div>
<div v-if="auth.isAdmin&&pending.length" class="finance-panel"><h2>Menunggu persetujuan <b>{{pending.length}}</b></h2><div v-for="p in pending" :key="p.id" class="pending-row"><div><button type="button" class="student-profile-link" :disabled="!p.student_id" @click="openStudentProfile(p.student_id)">{{studentName(p.student_id)}}</button><small>{{p.method.toUpperCase()}} · {{money(p.amount)}}</small><a v-if="p.proof_url" :href="p.proof_url" target="_blank" rel="noopener">Lihat bukti pembayaran</a></div><div class="actions"><button @click="review(p,'approved')"><Check :size="15"/> Setujui</button><button @click="review(p,'rejected')">Tolak</button></div></div></div>
<div v-if="auth.isAdmin" class="finance-panel"><h2>Hubungkan akun siswa</h2><p class="muted">Pilih akun yang sesuai dengan nomor absen agar pembayaran masuk ke baris siswa yang benar.</p><div v-for="st in students" :key="st.attendance_number" class="pending-row roster-link"><div><button type="button" class="student-profile-link roster-name" :disabled="!st.profile_id" @click="openStudentProfile(st.profile_id)">{{st.attendance_number}} · {{st.full_name}}</button><small>{{st.student_number}}</small></div><select :value="st.profile_id||''" @change="linkStudent(st,$event.target.value)"><option value="">Belum dihubungkan</option><option v-for="account in accountProfiles" :key="account.id" :value="account.id">{{account.display_name}}</option></select></div></div>
<div class="finance-panel"><h2>Rekap pembayaran bulanan</h2><p class="muted">Rp20.000 per siswa per bulan. Pembayaran lebih otomatis dialokasikan ke bulan tertua yang belum lunas.</p><div class="cash-table-wrap"><table class="cash-table"><thead><tr><th>No. absen / Nama</th><th v-for="m in months" :key="m.toISOString()">{{m.toLocaleDateString('id-ID',{month:'short',year:'2-digit'})}}</th></tr></thead><tbody><tr v-for="st in students" :key="st.attendance_number"><th><button type="button" class="student-profile-link table-student-name" :disabled="!st.profile_id" @click="openStudentProfile(st.profile_id)">{{st.attendance_number}} · {{st.full_name}}</button></th><td v-for="m in months" :key="m.toISOString()"><span :class="['cash-cell',cellClass(st.profile_id?monthPaid(st.profile_id,m):0)]">{{st.profile_id?(monthPaid(st.profile_id,m)>=20000?'✓':monthPaid(st.profile_id,m)>0?money(monthPaid(st.profile_id,m)):'−'):'—'}}</span></td></tr></tbody><tfoot><tr><th>Total masuk</th><td v-for="m in months" :key="m.toISOString()">{{money(monthTotal(m))}}</td></tr></tfoot></table></div></div>
<div v-if="auth.isAdmin" class="finance-panel"><h2>Kelola pengeluaran</h2><div v-for="item in expenses" :key="item.id" class="pending-row"><div><b>{{item.title}}</b><small>{{money(item.amount)}} · {{item.spent_at}}</small></div><div class="actions"><button @click="openExpense(item)">Edit</button><button @click="deleteExpense(item)">Hapus</button></div></div><p v-if="!expenses.length" class="muted">Belum ada pengeluaran.</p></div>
<div class="finance-panel"><h2>Riwayat transaksi</h2><p v-if="loading" class="muted">Memuat transaksi...</p><p v-else-if="!ledger.length" class="muted">Belum ada transaksi.</p><div v-for="item in ledger.slice(0,8)" :key="item.id" class="ledger-row"><span class="ledger-icon" :class="item.entry_type"><component :is="item.entry_type==='income'?ArrowDownLeft:ArrowUpRight"/></span><div class="ledger-info"><b>{{item.description}}</b><small>{{item.student_id?studentName(item.student_id):'Kas kelas'}} · {{new Date(item.occurred_at).toLocaleDateString('id-ID')}}</small></div><strong :class="item.entry_type">{{item.entry_type==='income'?'+':'−'}}{{money(item.amount)}}</strong></div></div>
<div v-if="error" class="error">{{error}}</div><div v-if="success" class="success">{{success}}</div><button class="fab" @click="auth.isAdmin?modal='actions':openPayment()"><Plus/></button>
</section><StudentProfileModal :profile-id="selectedStudentProfileId" @close="closeStudentProfile"/>
<div v-if="modal" class="modal-bg" @click.self="modal=''"><section class="finance-modal"><header><h2>{{modal==='payment'?'Bayar uang kas':modal==='expense'?(editingExpense?'Edit pengeluaran':'Tambah pengeluaran'):modal==='actions'?'Transaksi kas': 'Riwayat uang kas'}}</h2><button class="close" @click="modal=''"><X/></button></header>
<template v-if="modal==='actions'"><button class="choice" @click="openPayment()">Bayar uang kas</button><button class="choice" @click="openExpense()">Tambah pengeluaran</button><button class="choice" @click="modal='history'">Riwayat uang kas</button></template>
<template v-else-if="modal==='payment'"><label>Metode pembayaran<select v-model="payment.method"><option value="qris">QRIS</option><option value="cash">Tunai</option></select></label><div v-if="payment.method==='qris'" class="qris-placeholder"><b>QRIS kelas</b><small>Gambar QRIS belum ditambahkan. Admin dapat memasukkan qris-payment.png ke frontend/public/assets setelah kode QRIS tersedia.</small></div><label>Nominal pembayaran (Rp)<input v-model.number="payment.amount" type="number" min="1"/></label><label v-if="payment.method==='qris'">Bukti pembayaran<input type="file" accept="image/png,image/jpeg,image/webp" @change="payment.proof=$event.target.files?.[0]||null"/></label><label>Tanggal dan waktu pembayaran<input v-model="payment.paid_at" type="datetime-local"/></label><p class="muted">Pembayar: {{myRosterEntry?`${myRosterEntry.attendance_number} · ${myRosterEntry.full_name}`:(auth.user?.displayName||'Akun siswa')}}. Pembayaran baru masuk ke saldo setelah disetujui admin.</p><button class="primary" @click="submitPayment">Kirim pembayaran</button></template>
<template v-else-if="modal==='expense'"><label>Nama pengeluaran<input v-model="expense.title" placeholder="Contoh: Beli perlengkapan kelas"/></label><label>Nominal (Rp)<input v-model.number="expense.amount" type="number" min="1"/></label><label>Deskripsi<textarea v-model="expense.description" rows="3"/></label><label>Tanggal<input v-model="expense.spent_at" type="date"/></label><label>Foto struk (opsional)<input type="file" accept="image/png,image/jpeg,image/webp" @change="receiptFile=$event.target.files?.[0]||null"/></label><button class="primary" @click="addExpense">{{editingExpense?'Simpan perubahan':'Simpan pengeluaran'}}</button></template>
<template v-else><div v-for="item in ledger" :key="item.id" class="ledger-row"><span class="ledger-icon" :class="item.entry_type"><component :is="item.entry_type==='income'?ArrowDownLeft:ArrowUpRight"/></span><div class="ledger-info"><b>{{item.description}}</b><small>{{item.student_id?studentName(item.student_id):'Kas kelas'}} · {{new Date(item.occurred_at).toLocaleString('id-ID')}}</small></div><strong :class="item.entry_type">{{item.entry_type==='income'?'+':'−'}}{{money(item.amount)}}</strong></div></template>
</section></div></template>
<style scoped>
.finance-page{display:grid;gap:18px}.cash-table-wrap{overflow-x:auto;margin-top:12px}.cash-table{border-collapse:separate;border-spacing:4px;min-width:900px;font-size:11px}.cash-table th,.cash-table td{padding:8px 6px;text-align:center;white-space:nowrap}.cash-table thead th{background:#f4f6fa;border-radius:8px;color:var(--c-text-muted)}.cash-table thead th:first-child{position:sticky;left:0;z-index:3}.cash-table tfoot th{position:sticky;left:0;background:#f4f6fa;text-align:left}.cash-table tbody th{text-align:left;position:sticky;left:0;background:white;z-index:1;max-width:210px;overflow:hidden;text-overflow:ellipsis}.roster-link select{max-width:190px;min-width:130px;padding:8px;border:1px solid var(--c-border);border-radius:9px;background:white;font:inherit;font-size:11px}.cash-cell{display:inline-grid;place-items:center;min-width:44px;min-height:30px;padding:3px 5px;border-radius:8px;font-weight:800}.cash-cell.none{background:#ffe8e8;color:#c43c44}.cash-cell.low{background:#f6d1b7;color:#8e3d14}.cash-cell.half{background:#fff0b8;color:#8b6500}.cash-cell.full{background:#d9f5e4;color:#147a43}.balance-card{background:linear-gradient(135deg,#1c9a68,#126b58);color:white;border-radius:24px;padding:22px;box-shadow:var(--shadow-md)}.balance-card>div{display:flex;justify-content:space-between;align-items:center;font-size:13px;opacity:.9}.balance-card strong{display:block;font-size:30px;margin:16px 0 7px}.balance-card small{font-size:11px;opacity:.85}.history-icon{border:1px solid #ffffff66;background:#ffffff20;color:white;width:36px;height:36px;border-radius:50%;display:grid;place-items:center}.finance-panel{background:white;border:1px solid var(--c-border);border-radius:20px;padding:16px}.finance-panel h2{font-size:16px;margin-bottom:12px}.finance-panel h2 b{background:#fff0d6;color:#9a6200;border-radius:20px;padding:2px 8px;font-size:11px}.ledger-row,.pending-row{display:flex;align-items:center;gap:11px;padding:12px 0;border-top:1px solid var(--c-border)}.ledger-icon{width:36px;height:36px;border-radius:50%;display:grid;place-items:center}.ledger-icon.income{background:#e6f8ed;color:#16834c}.ledger-icon.expense{background:#ffeded;color:#d3434c}.ledger-info,.pending-row>div:first-child{display:grid;gap:4px;flex:1;min-width:0}.ledger-info b,.pending-row b{font-size:13px}.ledger-info small,.pending-row small{font-size:11px;color:var(--c-text-muted)}.pending-row a{font-size:11px;color:var(--c-primary)}.ledger-row strong{font-size:13px;white-space:nowrap}.income{color:#16834c}.expense{color:#d3434c}.actions{display:flex;gap:5px}.actions button{font-size:11px;padding:7px;border:1px solid var(--c-border);border-radius:9px;background:white}.fab{position:fixed;right:22px;bottom:calc(var(--nav-h) + 30px + env(safe-area-inset-bottom));width:56px;height:56px;border:0;border-radius:50%;background:var(--c-primary);color:white;display:grid;place-items:center;box-shadow:var(--shadow-primary);z-index:35}.modal-bg{position:fixed;inset:0;background:#1e293b66;z-index:100;display:flex;align-items:flex-end;justify-content:center;padding:12px}.finance-modal{width:min(100%,560px);max-height:88vh;overflow:auto;background:white;border-radius:24px;padding:20px}.finance-modal header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.finance-modal h2{font-size:18px}.close{border:0;border-radius:50%;width:34px;height:34px;background:#f1f3f7}.finance-modal label{display:grid;gap:6px;font-size:12px;font-weight:700;margin:12px 0}.finance-modal input,.finance-modal textarea,.finance-modal select{padding:11px;border:1px solid var(--c-border);border-radius:12px;font:inherit;background:white}.primary{width:100%;border:0;border-radius:12px;background:var(--c-primary);color:white;padding:13px;font-weight:800}.muted{font-size:12px;color:var(--c-text-muted)}.qris-placeholder img{max-width:190px;max-height:190px;object-fit:contain}.qris-placeholder{display:grid;justify-items:center;gap:6px;padding:20px;background:#f5f8fc;border:1px dashed #bdc9da;border-radius:15px;color:var(--c-text-muted);text-align:center}.qris-placeholder small{font-size:11px}.choice{width:100%;padding:14px;margin:5px 0;border:1px solid var(--c-border);border-radius:12px;background:white;text-align:left;font-weight:700}.error,.success{padding:10px;border-radius:12px;font-size:12px}.error{background:#fff0f0;color:#b42b36}.success{background:#e9f9ef;color:#167b48}.student-profile-link{display:inline;text-align:left;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;text-decoration:underline;text-decoration-color:var(--c-border);text-underline-offset:3px;cursor:pointer}.student-profile-link:hover{color:var(--c-primary)}.student-profile-link:disabled{cursor:default;text-decoration:none}.roster-name{font-size:11px;font-weight:700}.table-student-name{font-size:inherit;font-weight:800;max-width:230px;white-space:normal}@media(min-width:700px){.modal-bg{align-items:center}}
</style>
